-- Set the shared generated DB password on the roles Supabase's services
-- connect as. The roles themselves are created by the image's baked
-- migrations; this mirrors the official compose roles.sql but inline (no
-- psql \set) because the value is baked in at install time. IF EXISTS
-- guards keep it idempotent against image versions that skip a role.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'postgres') THEN
    ALTER ROLE postgres WITH LOGIN PASSWORD '{{generated:postgres_password}}';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticator') THEN
    ALTER ROLE authenticator WITH LOGIN PASSWORD '{{generated:postgres_password}}';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'pgbouncer') THEN
    ALTER ROLE pgbouncer WITH LOGIN PASSWORD '{{generated:postgres_password}}';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'supabase_auth_admin') THEN
    ALTER ROLE supabase_auth_admin WITH LOGIN PASSWORD '{{generated:postgres_password}}';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'supabase_storage_admin') THEN
    ALTER ROLE supabase_storage_admin WITH LOGIN PASSWORD '{{generated:postgres_password}}';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'supabase_functions_admin') THEN
    ALTER ROLE supabase_functions_admin WITH LOGIN PASSWORD '{{generated:postgres_password}}';
  END IF;
END
$$;

-- Record the generated JWT secret and expiry as database-level settings so
-- Studio's SQL editor and pg functions can read app.settings.* the same way
-- a managed Supabase instance does.
ALTER DATABASE postgres SET "app.settings.jwt_secret" TO '{{generated:jwt_secret}}';
ALTER DATABASE postgres SET "app.settings.jwt_exp" TO '3600';

\set pguser `echo "$POSTGRES_USER"`

create schema if not exists _realtime;
alter schema _realtime owner to :pguser;

